// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. unknown order returns 200). Do not "fix" these without
// deliberately changing the API contract.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.3, BIG: 100 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items', async () => {
  const body = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] })).json()
  assert.equal(body.total, 61)
})

test('total is floored to a whole number', async () => {
  const body = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  assert.equal(body.total, 25)
})

test('no discount at exactly 100', async () => {
  const body = await (await post({ items: [{ sku: 'BIG', qty: 1 }] })).json()
  assert.equal(body.total, 100)
})

test('10% discount when total is above 100', async () => {
  const body = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  assert.equal(body.total, 99)
})

test('discount is applied before flooring', async () => {
  // 25.5 * 5 = 127.5 -> 114.75 -> 114
  const body = await (await post({ items: [{ sku: 'B', qty: 5 }] })).json()
  assert.equal(body.total, 114)
})

test('fractional totals under 1 floor to 0', async () => {
  const body = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  assert.equal(body.total, 0)
})

test('extra item fields are echoed back', async () => {
  const items = [{ sku: 'A', qty: 1, note: 'x' }]
  const body = await (await post({ items })).json()
  assert.deepEqual(body.items, items)
})

for (const [name, payload, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'A' }],
  ['invalid JSON', null, '{nope'],
  ['null body', null, 'null'],
]) {
  test(`POST /orders 400 on ${name}`, async () => {
    const res = await post(payload, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('POST /orders with empty body is 400', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST' })
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('GET /orders/:id returns the created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes return 404 { error: "no route" }', async () => {
  for (const [method, path] of [
    ['GET', '/'],
    ['GET', '/orders'],
    ['GET', '/orders/1/extra'],
    ['PUT', '/orders/1'],
    ['DELETE', '/orders/1'],
    ['POST', '/orders/1'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 1 }] })
  const { id } = await res.json()
  const got = await fetch(`${base}/orders/${id}?x=1`)
  assert.equal((await got.json()).id, id)
})
EOF
